const items = $input.all();
const out = [];

function getProp(props, name) {
  const p = props[name];
  if (!p) return null;
  if (p.type === 'title') return (p.title?.[0]?.plain_text) || null;
  if (p.type === 'rich_text') return (p.rich_text?.[0]?.plain_text) || null;
  if (p.type === 'phone_number') return p.phone_number || null;
  if (p.type === 'select') return p.select?.name || null;
  if (p.type === 'number') return p.number;
  if (p.type === 'date') return p.date?.start || null;
  if (p.type === 'formula') return p.formula?.string || p.formula?.number || null;
  if (p.type === 'checkbox') return p.checkbox;
  return null;
}

for (const it of items) {
  const page = it.json;
  const props = page.property || page.properties || {};
  const phoneRaw = getProp(props, 'Telefone WhatsApp') || '';
  const phone = String(phoneRaw).replace(/\D/g, '');
  if (phone.length < 10) continue;

  const etapa = Number(getProp(props, 'Etapa Cadência WPP') || 0);
  const nome = getProp(props, 'Nome') || getProp(props, 'Cliente') || 'cliente';
  const plano = getProp(props, 'Plano') || '';
  const valor = getProp(props, 'Valor Renovação') || '';
  const vencimento = getProp(props, 'Vencimento') || '';
  const linkProposta = getProp(props, 'Link Proposta') || '';

  let nextEtapa = etapa;
  let nextDate = null;
  let nextStatus = null;
  let message = null;

  if (etapa === 1) {
    nextEtapa = 2;
    nextDate = $now.plus({ days: 4 }).toISODate();
    message = `Oi ${nome}, passando para reforçar a renovação do ${plano}` +
      (valor ? ` (${valor})` : '') +
      (vencimento ? `, com vencimento em ${vencimento}` : '') +
      `.${linkProposta ? `\n\nProposta: ${linkProposta}` : ''}` +
      `\n\nConsegue me dar um *sim* ou *não* para destravarmos por aqui?`;
  } else if (etapa === 2) {
    nextEtapa = 3;
    nextDate = null;
    nextStatus = 'Sem resposta';
    message = `${nome}, esta é nossa última tentativa por aqui antes de pausar a renovação do ${plano}.` +
      `\n\nSe quiser seguir, basta responder *sim* — caso contrário, posso te chamar por outro canal?`;
  } else {
    continue;
  }

  out.push({
    json: {
      pageId: page.id,
      phone,
      etapaAtual: etapa,
      proximaEtapa: nextEtapa,
      proximoDisparo: nextDate,
      novoStatus: nextStatus,
      message
    }
  });
}

return out;
